"""Static contract checks for the initial issue #4320 TUI prototype."""
from pathlib import Path

def main() -> int:
    root = Path(__file__).resolve().parents[2]
    tui = (root / "src" / "cli" / "cli_main.cpp").read_text(encoding="utf-8")
    tool = (root / "src" / "cli" / "tool_main.cpp").read_text(encoding="utf-8")
    required = {"FTXUI screen": "ScreenInteractive::TerminalOutput", "library surface": 'text("LIBRARY")', "analysis surface": 'text("TRACK ANALYSIS")', 'source path': 'text("Source: "', 'batch action': 'Button(" Analyze all "', 'batch progress': 'batch_completed', 'sort action': 'Sort: title', 'sort identity': 'Sorted visible Library by ', "live surface": 'text("LIVE")', 'live bpm correction': 'Button(" ½ BPM "', 'live reset': 'Button(" Reset / reacquire "', 'live correction state': 'live_bpm_multiplier', "settings surface": 'text("SETTINGS")', "interactive settings": 'Checkbox("Reduce motion"', "seek setting": 'Input(&seek_step_text', "real analyzer": "beatglass::replay_file", 'optional tonal analyzer': 'replay_music_file', 'tonal display': 'text("Key: "', 'tonal history': 'text("Tonal history: "', "progress status": "analysis_frames", "async analysis": "std::async(std::launch::async", "analysis cancellation": "analysis_stop.request_stop", "refresh cancellation": "Cancelling the previous analysis", "selection identity": "selection preserved by path", "selection cancellation": "Cancelling analysis because the selected track changed", "analysis reentry guard": "Analysis already in progress", "stale analysis guard": "Analysis finished for a previous track", "no track playback feedback": "Select a supported audio file before starting playback", "portable playback status": "Native playback is unavailable in this build", "waveform cancellation": "decode_waveform(path, stop_token)", "waveform legend": 'text("PCM amplitude")', "real beat positions": "beat_frames", "cancel action": 'Button(" Cancel analysis "', "custom completion event": "Event::Custom", "audio discovery": "std::filesystem::recursive_directory_iterator", "library filter": "Input(&filter", "folder control": 'Input(&folder_text', "folder action": 'Button(" Open folder "', "native folder picker": "FOS_PICKFOLDERS", "refresh sinks": 'Button(" Refresh sinks "', "live selection lifecycle": "Capture stopped because the selected sink changed", "live refresh lifecycle": "Capture stopped while render sinks were refreshed", "stale sink validation": "select_render_endpoint", "live telemetry": 'live_observed_frames', "live button state sync": 'live_button_label = " Start monitoring "', "keyboard navigation": "MenuOption", "tab shortcuts": 'Event::Character("1")', "tab cycling": "Event::Tab", "mouse tabs": "Button(\"  [1] Library  \"", "visible tab shortcuts": "Button(\"  [3] Settings  \"", "tonal capability status": "Tonal analysis: unavailable", "fullscreen layout": "| flex", "compact terminal": "needs more room", "open-folder shortcut": 'Event::Character("o")', "waveform chart": "waveform_chart", "waveform cursor": "playback_fraction", "spinner": "spinner(6", "analyze action": "Event::Return", "playback shortcut": 'Event::Character(" ")', "playback position": "current_frame()", "seek controls": 'seek_seconds', "cli version": '"beatglass-cli "', "cli help": 'Usage: beatglass-cli', "snapshot tab validation": "Invalid snapshot tab", "tool rename": "beatglass-tool", "error recovery": 'status = std::string("Analysis failed: ")'}
    missing = [name for name, marker in required.items() if marker not in (tool if name == "tool rename" else tui)]
    if missing: raise SystemExit("Missing issue #4320 TUI markers: " + ", ".join(missing))
    print(f"Issue #4320 TUI contract markers verified ({len(required)} checks)")
    return 0

if __name__ == "__main__": raise SystemExit(main())
